const http = require('node:http');
const https = require('node:https');
const fetch = globalThis.fetch || ((urlString, options = {}) => new Promise((resolve, reject) => {
  const transport = String(urlString).startsWith('https://') ? https : http;
  const req = transport.request(urlString, {
    method: options.method || 'GET',
    headers: options.headers || {},
  }, (res) => {
    let body = '';
    res.on('data', (chunk) => {
      body += chunk.toString();
    });
    res.on('end', () => {
      resolve({
        ok: (res.statusCode || 0) >= 200 && (res.statusCode || 0) < 300,
        status: res.statusCode || 0,
        text: async () => body,
        json: async () => body ? JSON.parse(body) : {},
      });
    });
  });
  req.on('error', reject);
  if (options.body) {
    req.write(options.body);
  }
  req.end();
}));

const runnerBase = $env.AUTOMATION_RUNNER_BASE_URL;
const runnerToken = $env.AUTOMATION_RUNNER_TOKEN;
if (!runnerBase) throw new Error('AUTOMATION_RUNNER_BASE_URL is not configured');

const response = $input.first().json;
const workItems = Array.isArray(response.results) ? response.results : [];

const compactItems = workItems.map((item) => ({
  id: item.id,
  title: item.name,
  priority: item.priority ?? 'none',
  state: item.state ?? 'unknown',
  updatedAt: item.updated_at,
  completedAt: item.completed_at ?? null,
  summary: (item.description_stripped ?? '').replace(/\s+/g, ' ').trim().slice(0, 240),
}));

const prompt = [
  'You are summarizing daily project activity for the Wazaker mobile app project.',
  'Write a concise markdown summary for the founder.',
  'Use exactly these sections: Overview, High Priority, Recently Updated, Watchlist.',
  'Mention concrete work item titles when helpful.',
  'Do not invent statuses, owners, or outcomes.',
  'If a section has nothing notable, write None.',
  '',
  'Work items:',
  JSON.stringify(compactItems, null, 2),
].join('\n');

let summary = '';
let summarySource = 'ollama';
try {
  const ollamaResponse = await fetch('http://host.docker.internal:11434/api/generate', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: 'qwen3:8b',
      prompt,
      stream: false,
    }),
  });

  if (!ollamaResponse.ok) {
    const body = await ollamaResponse.text();
    throw new Error(`Ollama request failed: ${ollamaResponse.status} ${body}`);
  }

  const ollamaJson = await ollamaResponse.json();
  summary = (ollamaJson.response ?? '').trim();
} catch (error) {
  summarySource = 'fallback';
  const highPriority = compactItems.filter((item) => ['urgent', 'high'].includes(String(item.priority || '').toLowerCase())).map((item) => `- ${item.title}`).slice(0, 5);
  const recentlyUpdated = [...compactItems].sort((left, right) => String(right.updatedAt || '').localeCompare(String(left.updatedAt || ''))).slice(0, 5).map((item) => `- ${item.title}`);
  const watchlist = compactItems.filter((item) => !item.completedAt && String(item.state || '').toLowerCase() !== 'done').slice(0, 5).map((item) => `- ${item.title}`);
  summary = [
    '## Overview',
    '',
    `Fallback summary generated because the Ollama request was unavailable: ${error instanceof Error ? error.message : String(error)}`,
    '',
    '## High Priority',
    '',
    ...(highPriority.length > 0 ? highPriority : ['None.']),
    '',
    '## Recently Updated',
    '',
    ...(recentlyUpdated.length > 0 ? recentlyUpdated : ['None.']),
    '',
    '## Watchlist',
    '',
    ...(watchlist.length > 0 ? watchlist : ['None.']),
  ].join('\n');
}

const dateStamp = new Date().toISOString().slice(0, 10);
const reportRelativePath = `daily-plane-summaries/${dateStamp}.md`;
const reportContent = [
  '# Daily Plane Summary',
  '',
  `Generated: ${new Date().toISOString()}`,
  `Included work items: ${compactItems.length}`,
  `Summary source: ${summarySource}`,
  '',
  summary || 'No summary generated.',
  '',
  '## Included Work Items',
  ...compactItems.map((item) => `- ${item.title} [priority=${item.priority}]`),
].join('\n');

const writeResponse = await fetch(`${runnerBase}/reports/write`, {
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    ...(runnerToken ? { Authorization: `Bearer ${runnerToken}` } : {}),
  },
  body: JSON.stringify({
    relativePath: reportRelativePath,
    content: reportContent,
  }),
});

if (!writeResponse.ok) {
  const body = await writeResponse.text();
  throw new Error(`Runner report write failed: ${writeResponse.status} ${body}`);
}

return [{
  json: {
    generatedAt: new Date().toISOString(),
    itemCount: compactItems.length,
    summary,
    summarySource,
    reportRelativePath,
    workItems: compactItems,
  },
}];
